-- Independent Dadyoom teaching supports, not claims about the contents of official books.
-- Idempotent: update only empty or short default placeholder published lessons; add each origin/type once.
DO $dadyoom$
DECLARE
  r RECORD;
  target_id uuid;
  target_content text;
BEGIN
  FOR r IN SELECT * FROM jsonb_to_recordset('[{"n":10,"skill":"فهم الانطباعات وتحديد الدليل","passage":"نص إثرائي مستقل: «وصل زائر إلى المنامة، فلاحظ الأسواق المتجاورة مع المباني الحديثة، واستمع إلى حكايات أهل المكان. دوّن أن جمال المدينة يظهر في عمرانها ولقاء الناس». نستدل من الأمثلة على التنوع دون أن ننسب الوصف إلى درس «البحرين في عيون زائريها» نفسه.","prompt":"ما التفصيل الذي يثبت تنوع المشهد في النص المستقل؟","correct":"تجاور الأسواق والمباني الحديثة","w1":"لون حقيبة الزائر","w2":"موعد الحصة الرياضية","w3":"عدد صفحات الدفتر","practice":"اكتب انطباع زائر عن مكان في البحرين مع وصف ملموس وحكم تذكر دليله."},{"n":11,"skill":"فهم الرمز والمثابرة","passage":"نموذج مستقل: «نبتت زهرة صغيرة قرب حجر مرتفع، فمالت نحو الضوء، وبقيت تقاوم الظل حتى أزهرت». تظهر المثابرة من تكرار المحاولة، لكن هذه قصة من ضاديوم وليست نص «البنفسجة الطموح».","prompt":"بأي فعل ظهرت المثابرة في المثال؟","correct":"ميل الزهرة نحو الضوء ومقاومة الظل","w1":"الوقوف عن النمو","w2":"اختفاء الضوء نهائيًا","w3":"ترك المكان","practice":"اشرح في خمسة أسطر كيف تصنع المثابرة فرقًا في موقف واقعي مع مثال واضح."},{"n":12,"skill":"أثر الصداقة في السلوك","passage":"نموذج مستقل: «كان سامي يتردد في المشاركة، فشجعه صديقه على القراءة أمام الصف، ثم تدربا معًا حتى زال خوفه». نقيّم أثر الصحبة من الأفعال لا من الألقاب؛ ولا نزعم اقتباس النص المعنون «حدثني عمن تصاحب».","prompt":"كيف أثر الصديق في سامي؟","correct":"شجعه على التدريب والمشاركة","w1":"منعه من المحاولة","w2":"تجاهل خوفه","w3":"سخر من قراءته","practice":"اكتب موقفًا قصيرًا يبين كيف تؤثر الصداقة في اتخاذ قرار، مع شاهد من الحدث."},{"n":13,"skill":"القيادة والمسؤولية في سن مبكرة","passage":"نموذج مستقل: «اختيرت هدى لتنظيم معرض الطلاب وهي في السادسة عشرة. قسمت المهام واستشارت زملاءها، فنجح العمل الجماعي». يظهر معنى القيادة في توزيع المسؤولية والاستماع، دون نسبة الوقائع إلى نص «قائد دون العشرين».","prompt":"أي فعل يبين مهارة القيادة لدى هدى؟","correct":"تقسيم المهام واستشارة الزملاء","w1":"العمل وحدها ورفض الآراء","w2":"تجاهل الخطة","w3":"إلغاء المعرض","practice":"صف مشروعًا يقوده شاب، واذكر قرارين ومسؤولية كل عضو ونتيجة العمل."},{"n":14,"skill":"التمييز بين النص القرآني والتفسير","passage":"لا يمكن تقديم شرح للآيات المحددة من سورة فصلت دون تحديد مواضعها والرجوع إلى المصحف وتفسير موثوق. في تدريب مستقل على الاستدلال: «يتأمل المرء نظام الكون فيزداد حرصًا على حسن العمل». هذه العبارة ليست آية قرآنية ولا تفسيرًا رسميًا؛ والتوثيق واجب في درس القرآن.","prompt":"لماذا ينبغي الرجوع إلى نص الآيات عند التفسير؟","correct":"لتوثيق الألفاظ والسياق وتجنب نسبة كلام غير صحيح","w1":"لتغيير نص الآية","w2":"لتأليف آيات جديدة","w3":"لإلغاء قواعد التلاوة","practice":"حدّد الآيات المطلوبة من مصدر معتمد بمعاونة المعلم، واستخرج قيمة واحدة بدليل من الآية مع ذكر رقمها الصحيح."},{"n":25,"skill":"الفكرة الرئيسة والتفاصيل في موضوع المياه","passage":"نص مستقل: «تعتمد مناطق الخليج على ترشيد الاستهلاك وتحسين إدارة المياه. يقل الهدر حين تصلح التسريبات وتستخدم أدوات اقتصادية». نحدد السبب والنتيجة دون ادعاء إحصاءات أو نقل نص درس «التنمية المائية في دول الخليج».","prompt":"أي سلوك يقلل الهدر في النص التدريبي؟","correct":"إصلاح التسريبات","w1":"ترك الصنبور مفتوحًا","w2":"إهمال الأنابيب","w3":"زيادة الاستهلاك","practice":"اكتب فقرة عن وسيلتين لترشيد المياه وفسر أثر كل وسيلة منطقيًا."},{"n":26,"skill":"تذوق الصورة الشعرية بعناية","passage":"لتذوق قصيدة «الخليج العربي» ينبغي الرجوع إلى أبياتها الفعلية، خاصة الأبيات المطلوبة للحفظ، وعدم اختلاق شاهد شعري. في نموذج نثري مستقل: «امتد البحر أمام الصيادين، وربطهم الموج برحلات الآباء». يمكن تحليل ارتباط المكان بالذاكرة من دون نسبته إلى شاعر القصيدة.","prompt":"ما العلاقة بين البحر والذاكرة في النموذج المستقل؟","correct":"يستدعي رحلات الآباء","w1":"يمنع التذكر","w2":"يدل على الصحراء فقط","w3":"يلغي وصف المكان","practice":"بعد قراءة الأبيات الأصلية اختر صورة شعرية موثقة، واكتب شرحها بجملة تتضمن دليلًا لفظيًا."},{"n":27,"skill":"استنتاج العاطفة من الألفاظ","passage":"لا نورد أبياتًا مصطنعة لقصيدة «حب وإيمان» ولا نحدد ما يقصد الشاعر دون النص. تدريب مستقل: «أعتز بأهلي وأحفظ الجميل لمن أحسن إليّ؛ فالإخلاص يظهر في الفعل». الكلمات «أعتز» و«أحفظ الجميل» تدعم معنى الوفاء.","prompt":"أي كلمة في النموذج تدل على الاعتزاز؟","correct":"أعتز","w1":"لمن","w2":"في","w3":"يظهر","practice":"استخرج من القصيدة في نسختك لفظتين تدلان على عاطفة واحدة، ثم علل اختيارك مع توثيق البيت."},{"n":28,"skill":"تفسير تشبيه من نص مستقل","passage":"تدريب في التعبير المجازي: «الكتاب نافذة تفتح للخيال مشاهد جديدة». النافذة هنا تشبيه وظيفته تقريب أثر القراءة؛ فالقارئ لا يرى نافذة حقيقية. لا ننسب العبارة إلى القراءة المعنونة «عصير الذهن».","prompt":"ما المقصود بالنافذة في العبارة؟","correct":"اتساع المعرفة والخيال بالقراءة","w1":"نافذة البيت الفعلية","w2":"إغلاق الصف","w3":"صوت النافذة","practice":"اكتب ثلاث استعارات أو تشبيهات مرتبطة بالتعلم، واشرح واحدًا بلغة واضحة."},{"n":29,"skill":"الإصغاء واحترام المتحدث","passage":"حوار تدريبي: «تكلمت مريم عن مشروعها، فأغلق زميلها هاتفه، ونظر إليها، ثم سأل سؤالًا مرتبطًا بما قالت». نميز الإصغاء الفعال عن مجرد الصمت، فالسؤال المرتبط دليل فهم ومتابعة. هذا تدريب مستقل عن نص «فن الإصغاء».","prompt":"ما السلوك الأقوى دلالة على فهم المستمع؟","correct":"سؤال مرتبط بكلام مريم","w1":"مقاطعتها باستمرار","w2":"الانشغال بالهاتف","w3":"النظر بعيدًا","practice":"اكتب قواعد خمسًا للإصغاء، ثم صمم حوارًا قصيرًا يبين واحدة منها عمليًا."},{"n":30,"skill":"قراءة الشعر وتحديد الإيقاع دون اختلاق أبيات","passage":"يتطلب درس «من أغاني الرعاة» مراجعة القصيدة الأصلية لتحديد الأبيات والمقطعين المطلوبين للحفظ. في تدريب مستقل نثري: «يرعى الراعي قطيعه في الصباح، ويسمع حركة الأغنام في الوادي». نميّز المشهد الطبيعي من الوصف الإيقاعي الشعري ولا ندعي أن النموذج بيت من القصيدة.","prompt":"أين يدور المشهد في النص التدريبي؟","correct":"في الوادي صباحًا","w1":"في قاعة المدرسة","w2":"في السوق مساءً","w3":"في الميناء ليلًا","practice":"اقرأ المقطعين المطلوبين من نسخة القصيدة المعتمدة، وحدد صورتين واضحتين وفسر أثر إيقاع أحد الأبيات بمساعدة المعلم."}]'::jsonb) AS x(
    n integer,skill text,passage text,prompt text,correct text,w1 text,w2 text,w3 text,practice text
  ) LOOP
    SELECT l.id,l.content INTO STRICT target_id,target_content
    FROM public.lessons l
    JOIN public.units u ON u.id=l.unit_id
    JOIN public.grades g ON g.id=u.grade_id AND g.grade_number=8
    JOIN public.curricula cu ON cu.id=g.curriculum_id AND cu.academic_year='2026-2027'
    JOIN public.countries c ON c.id=cu.country_id AND c.code='BH'
    WHERE u.title='القراءة والنصوص' AND u.semester=1 AND l.sort_order=r.n AND l.status='published'
    FOR UPDATE OF l;
    IF coalesce(trim(target_content),'')='' OR (target_content LIKE 'يتناول هذا الدرس موضوع%' AND char_length(target_content)<350) THEN
      UPDATE public.lessons SET
        content='ضاديوم — إثراء مستقل أصلي للصف الثامن، الفصل الأول. لا يمثل النص الوزاري الأصلي ولا يثبت مطابقة العنوان للمصدر.'||E'\n\n'||
          'المهارة: '||r.skill||E'\n\n'||
          'النموذج التعليمي والشرح: '||r.passage||E'\n\n'||
          'أهداف التعلم: يحدد المتعلم شاهدًا صحيحًا ويشرح دلالته، ويميّز بين الفكرة والدليل، ثم ينتج كتابة مناسبة للمهارة.'||E'\n\n'||
          'سؤال الفهم: '||r.prompt||E'\n\n'||
          'التطبيق الكتابي: '||r.practice||E'\n\n'||
          'التمايز: المبتدئ يحصل على كلمات مفتاحية وبداية جملة؛ المتوسط يجيب بدليل مستقل؛ المتقدم يقارن بين صياغتين ويبرر تحسيناته.'||E'\n\n'||
          'مراجعة المعلم: تحقق من صحة الاستدلال والإملاء وعلامات الترقيم والترابط. لا تُمنح درجة جودة تلقائية لمجرد تسليم المهمة.'||E'\n\n'||
          'تنبيه المصدر: راجع العنوان المستورد والكتاب الرسمي قبل وصف هذا التدريب بأنه مطابق للمنهج.'||E'\n\n'||'المدخل السابق المحفوظ: '||coalesce(target_content,''),
        updated_at=now()
      WHERE id=target_id;
    END IF;
    IF EXISTS (SELECT 1 FROM public.lessons WHERE id=target_id AND content LIKE 'ضاديوم — إثراء مستقل أصلي للصف الثامن%') THEN
      INSERT INTO public.lesson_activities (lesson_id,title,activity_type,section,prompt,content,answer,activity_order,points,is_required,is_published)
      SELECT target_id,'فهم النص الإثرائي','multiple_choice','assessment',r.prompt,
        jsonb_build_object('origin','DADYOOM_BH_G8_T1_READING_11_20261008','notOfficialBook',true,'ocrReview','pending','options',jsonb_build_array(r.correct,r.w1,r.w2,r.w3)),
        jsonb_build_object('correct',r.correct),
        coalesce((SELECT max(activity_order) FROM public.lesson_activities WHERE lesson_id=target_id),0)+1,5,true,true
      WHERE NOT EXISTS (SELECT 1 FROM public.lesson_activities WHERE lesson_id=target_id AND activity_type='multiple_choice' AND content->>'origin'='DADYOOM_BH_G8_T1_READING_11_20261008');
      INSERT INTO public.lesson_activities (lesson_id,title,activity_type,section,prompt,content,answer,activity_order,points,is_required,is_published)
      SELECT target_id,'كتابة تطبيقية بمراجعة المعلم','writing','practice',r.practice,
        jsonb_build_object('origin','DADYOOM_BH_G8_T1_READING_11_20261008','notOfficialBook',true,'humanReviewRequired',true,'text',r.practice,'skillQualityAutoVerified',false),
        jsonb_build_object('grading_mode','completion_only_reference','model_answer','لا تكفي المطابقة النصية؛ يصحح المعلم ملاءمة الأفكار والدليل والترابط.'),
        coalesce((SELECT max(activity_order) FROM public.lesson_activities WHERE lesson_id=target_id),0)+1,5,true,true
      WHERE NOT EXISTS (SELECT 1 FROM public.lesson_activities WHERE lesson_id=target_id AND activity_type='writing' AND content->>'origin'='DADYOOM_BH_G8_T1_READING_11_20261008');
    END IF;
  END LOOP;
END
$dadyoom$;